// Pin definitions for motors
const int leftMotorForward = 5;
const int leftMotorBackward = 6;
const int rightMotorForward = 9;
const int rightMotorBackward = 10;

// Pin definitions for Ultrasonic Sensor (HC-SR04)
const int trigPin = 12;
const int echoPin = 11;

// Constants
const int motorSpeed = 200; // PWM value (0-255)
const int safeDistance = 20; // Distance in cm to avoid obstacles

void setup() {
  // Set motor pins as outputs
  pinMode(leftMotorForward, OUTPUT);
  pinMode(leftMotorBackward, OUTPUT);
  pinMode(rightMotorForward, OUTPUT);
  pinMode(rightMotorBackward, OUTPUT);

  // Set ultrasonic sensor pins
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);

  // Initialize serial communication for debugging
  Serial.begin(9600);
}

void loop() {
  int distance = getDistance();

  Serial.print("Distance: ");
  Serial.print(distance);
  Serial.println(" cm");

  if (distance > safeDistance) {
    // No obstacle, move forward
    moveForward();
  } else {
    // Obstacle detected
    stopRobot();
    delay(500); // Pause briefly
    turnRight(); // Turn right to avoid
    delay(500); // Wait for turn to complete
    stopRobot();
  }
}

// Function to read distance from ultrasonic sensor
int getDistance() {
  long duration, distance;

  // Clear the trigPin
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);

  // Set the trigPin on HIGH state for 10 micro seconds
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  // Read the echoPin, returns the sound wave travel time in microseconds
  duration = pulseIn(echoPin, HIGH);

  // Calculate the distance
  distance = duration * 0.034 / 2;

  return distance;
}

// Motor Control Functions
void moveForward() {
  analogWrite(leftMotorForward, motorSpeed);
  analogWrite(leftMotorBackward, 0);
  analogWrite(rightMotorForward, motorSpeed);
  analogWrite(rightMotorBackward, 0);
